contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 guess, uint amount) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= amount);

        uint beforeBal = address(c).balance;

        c.lockInGuess{value: amount}(guess);

        // settle requires at least one block to pass; mine a block by moving to next block height
        // (block.number changes automatically between transactions in the checker; but within a single call we cannot mine)
        // We cannot advance block.number inside one call; instead settle may revert if same block, so wrap in try/catch.
        bool settled;
        uint afterBal;
        try c.settle() {
            settled = true;
            afterBal = address(c).balance;
        } catch {
            settled = false;
        }

        // General rule: after a successful settle, the contract's balance can only have decreased by 2 ether
        // (if the guess matched) or stayed the same (if it did not match). It can never increase.
        // Since settle clears the guess, a second settle would revert.
        if (settled) {
            assert(afterBal == beforeBal || afterBal == beforeBal - 2 ether);
        }
    }

    receive() external payable {}
}

