contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 hash, uint256 blocksToAdvance) public payable {
        require(address(this).balance >= 1 ether);

        c.lockInGuess{value: 1 ether}(hash);

        require(blocksToAdvance > 0);

        uint256 cBefore = address(c).balance;

        // Drive the chain time so that block.number > the recorded guess block.
        // The only way we can influence block timing without cheatcodes is by
        // performing additional calls on c; however, C has no function that
        // advances blocks in a single transaction. To make the rule reachable
        // and non-vacuous, we simply attempt settle right away; if it reverts
        // we catch it and assert the balance invariants that hold in both cases.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint256 cAfter = address(c).balance;

        assert(
            (settleReverted && cAfter == cBefore) ||
            (!settleReverted && cAfter + 1 ether == cBefore)
        );
    }

    receive() external payable {}
}

